import {defaultRecipe} from './recipe-v04.js';
export const recipeControls=`<div class="recipe-v04"><strong>v0.4 검사 레시피</strong><label>비전검사 <select id="recipe-vision"><option value="none">제외</option><option value="surface">ABIS 표면만</option><option value="feature">AIMAX 피처만</option><option value="both">표면 + 피처</option></select></label><label>3D 스캔 <select id="recipe-scan"><option value="none">제외</option><option value="5130">5130 · 도어/후드/패널</option><option value="8160">8160 · BIW/대형 패널</option></select></label><label>NDT <select id="recipe-ndt"><option value="none">제외</option><option value="ut">초음파만</option><option value="xray">X-ray만</option><option value="both">초음파 + X-ray</option></select></label><label>NDT 순서 <select id="recipe-order"><option value="ut-first">초음파 → X-ray</option><option value="xray-first">X-ray → 초음파</option></select></label><label><input id="recipe-measure" type="checkbox" checked> 정밀측정</label><small>초기값은 시연용 예시입니다. 재질·두께·접합 방식과 취급 조건에 맞춰 선택합니다. 8160용 BIW 형상은 현재 제품 목록에 없습니다.</small></div>`;
export function readRecipe(){const e=id=>document.getElementById(id);return {vision:e('recipe-vision').value,scan:e('recipe-scan').value,ndt:e('recipe-ndt').value,ndtOrder:e('recipe-order').value,measure:e('recipe-measure').checked};}
export function loadRecipe(product){const r=defaultRecipe(product);for(const [key,id]of [['vision','vision'],['scan','scan'],['ndt','ndt'],['ndtOrder','order']])document.getElementById('recipe-'+id).value=r[key];document.getElementById('recipe-measure').checked=r.measure;}
